diff --git a/test/ranges-test.cc b/test/ranges-test.cc
--- a/test/ranges-test.cc
+++ b/test/ranges-test.cc
@@ -15,6 +15,10 @@
 #include <string>
 #include <vector>

+#if FMT_HAS_INCLUDE(<ranges>) && FMT_CPLUSPLUS >= 202002L
+#  include <ranges>
+#endif
+
 #include "gtest/gtest.h"

 #if !FMT_GCC_VERSION || FMT_GCC_VERSION >= 601
@@ -442,3 +446,68 @@
 TEST(ranges_test, vector_char) {
   EXPECT_EQ(fmt::format("{}", std::vector<char>{'a', 'b'}), "['a', 'b']");
 }
+
+TEST(ranges_test, nested_char_range) {
+  auto v = std::vector<std::vector<char>>{{'a'}, {'b', '\n'}, {}};
+  EXPECT_EQ(fmt::format("{}", v), "[['a'], ['b', '\\n'], []]");
+  EXPECT_EQ(fmt::format("{::}", v), "[['a'], ['b', '\\n'], []]");
+  EXPECT_EQ(fmt::format("{:n}", v), "['a'], ['b', '\\n'], []");
+  EXPECT_EQ(fmt::format("{:::}", v), "[[a], [b, \n], []]");
+}
+
+TEST(ranges_test, nested_string_range) {
+  auto v = std::vector<std::vector<std::string>>{{"a", "b\n"}, {}};
+  EXPECT_EQ(fmt::format("{}", v), "[[\"a\", \"b\\n\"], []]");
+  EXPECT_EQ(fmt::format("{:::}", v), "[[a, b\n], []]");
+}
+
+#if defined(__cpp_lib_ranges) && __cpp_lib_ranges >= 202110L
+TEST(ranges_test, split_view) {
+  auto line = std::string("a,b-c,d-e,f");
+  EXPECT_EQ(fmt::format("{}", line | std::views::split(',')),
+            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
+}
+
+struct non_const_char_range {
+  std::string_view sv;
+
+  template <std::ranges::range R>
+  explicit non_const_char_range(R&& r)
+      : sv(std::ranges::data(r), std::ranges::size(r)) {}
+
+  auto begin() { return sv.begin(); }
+  auto end() { return sv.end(); }
+};
+
+TEST(ranges_test, transform_view_of_non_const_ranges) {
+  auto line = std::string("a,b-c,d-e,f");
+  auto r = line | std::views::split(',') |
+           std::views::transform([](auto part) {
+             return non_const_char_range(part);
+           });
+  EXPECT_EQ(fmt::format("{}", r),
+            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
+
+  auto empty = std::string(",");
+  auto empty_ranges = empty | std::views::split(',') |
+                      std::views::transform([](auto part) {
+                        return non_const_char_range(part);
+                      });
+  EXPECT_EQ(fmt::format("{}", empty_ranges), "[[], []]");
+}
+
+TEST(ranges_test, transform_view_of_split_views) {
+  auto line = std::string("a,b-c,d-e,f");
+  auto r = line | std::views::split(',') |
+           std::views::transform(std::views::split('-'));
+  EXPECT_EQ(fmt::format("{}", r),
+            "[[['a']], [['b'], ['c']], [['d'], ['e']], [['f']]]");
+}
+#endif
